using System.Runtime.CompilerServices;
using System.Threading;
namespace XamlG.Runtime;

/// <summary>Owns generated-object inspection and reversible setters without rooting application windows globally.</summary>
public sealed class XamlRuntimeSession : IDisposable
{
    private static readonly ConditionalWeakTable<object, XamlRuntimeSession> Sessions = new();
    private readonly Dictionary<string, XamlRuntimeNode> _nodes = new(StringComparer.Ordinal);
    private readonly Dictionary<(string Node, string Member), XamlRuntimeProperty> _properties = new();
    private readonly List<Action> _cleanup = new();
    private readonly int _threadId = Thread.CurrentThread.ManagedThreadId;
    private bool _disposed;
    private bool _applying;
    public long Revision { get; private set; }
    public IReadOnlyCollection<XamlRuntimeNode> Nodes => _nodes.Values;
    public static bool TryGet(object root, out XamlRuntimeSession? session) => Sessions.TryGetValue(root, out session);
    public void Attach(object root)
    {
        CheckThread();
        if (Sessions.TryGetValue(root, out var previous) && !ReferenceEquals(previous, this)) { previous.Dispose(); Sessions.Remove(root); }
        if (!Sessions.TryGetValue(root, out _)) Sessions.Add(root, this);
    }
    public void Register(string key, object instance, string? parentKey)
    {
        CheckThread();
        if (_nodes.TryGetValue(key, out var old) && !ReferenceEquals(old.Instance, instance)) throw new InvalidOperationException($"Duplicate generated node key '{key}'.");
        _nodes[key] = new(key, instance, parentKey);
    }
    public void RegisterProperty<T>(string key, string member, Func<T> getter, Action<T> setter)
    {
        CheckThread(); _properties[(key, member)] = new(typeof(T), () => getter(), value => setter((T)value!));
    }
    public void TrackCleanup(Action action) { CheckThread(); _cleanup.Add(action ?? throw new ArgumentNullException(nameof(action))); }
    public XamlMutationResult Apply(long expectedRevision, IReadOnlyList<XamlPropertyUpdate> updates)
    {
        CheckThread();
        if (expectedRevision != Revision) return new(false, Revision, "The live view has a different revision.");
        if (_applying) return new(false, Revision, "A reentrant update is not permitted.");
        var pending = new List<(XamlRuntimeProperty Property, object? Before, object? After)>();
        var keys = new HashSet<(string, string)>();
        foreach (var update in updates)
        {
            if (!keys.Add((update.NodeKey, update.MemberName))) return new(false, Revision, "The batch assigns a property more than once.");
            if (!_properties.TryGetValue((update.NodeKey, update.MemberName), out var property)) return new(false, Revision, $"'{update.NodeKey}.{update.MemberName}' requires a structural rebuild.");
            if (!property.Accepts(update.Value)) return new(false, Revision, $"The replacement value is not assignable to '{property.Type}'.");
            try { pending.Add((property, property.Get(), update.Value)); }
            catch (Exception error) { return new(false, Revision, "A property getter failed: " + error.Message); }
        }
        _applying = true; var applied = 0;
        try
        {
            for (; applied < pending.Count; applied++) pending[applied].Property.Set(pending[applied].After);
            Revision = checked(Revision + 1); return new(true, Revision, null);
        }
        catch (Exception error)
        {
            var failures = new List<Exception> { error };
            for (var i = Math.Min(applied, pending.Count - 1); i >= 0; i--)
                try { pending[i].Property.Set(pending[i].Before); } catch (Exception rollback) { failures.Add(rollback); }
            if (failures.Count > 1) throw new AggregateException("The update and at least one rollback operation failed; rebuild the view.", failures);
            return new(false, Revision, error.Message);
        }
        finally { _applying = false; }
    }
    public void Dispose()
    {
        if (_disposed) return; CheckThread(); _disposed = true; var errors = new List<Exception>();
        for (var i = _cleanup.Count - 1; i >= 0; i--) try { _cleanup[i](); } catch (Exception error) { errors.Add(error); }
        _cleanup.Clear(); _properties.Clear(); _nodes.Clear();
        if (errors.Count != 0) throw new AggregateException("Generated event cleanup failed.", errors);
    }
    private void CheckThread()
    {
        if (_disposed) throw new ObjectDisposedException(nameof(XamlRuntimeSession));
        if (Thread.CurrentThread.ManagedThreadId != _threadId) throw new InvalidOperationException("Generated view mutations must run on the view's owning thread.");
    }
}

namespace XamlG.Runtime;
internal sealed class XamlNameScope
{
    private readonly Dictionary<string, object> _names = new(StringComparer.Ordinal);
    private readonly List<Action> _fixups = new();
    public void Register(string name, object value)
    {
        if (_names.ContainsKey(name)) throw new InvalidOperationException($"Duplicate XAML name '{name}'.");
        _names.Add(name, value);
    }
    public object Resolve(string name) => _names.TryGetValue(name, out var value) ? value : throw new InvalidOperationException($"XAML name '{name}' was not registered.");
    public void Defer(Action assignment) => _fixups.Add(assignment);
    public void Complete()
    {
        var pending = _fixups.ToArray(); _fixups.Clear();
        foreach (var assignment in pending) assignment();
    }
}

namespace XamlG.Runtime;

/// <summary>Persistent service-provider frames preserve parent and target semantics across nested and deferred construction.</summary>
public sealed class XamlRuntimeContext : IServiceProvider, IXamlRootObjectProvider, IXamlProvideValueTarget, IXamlParentStackProvider, IXamlUriContext
{
    private readonly IServiceProvider? _outer;
    private readonly Func<XamlRuntimeContext, Type, object?>? _services;
    private readonly XamlRuntimeContext? _parent;
    private readonly object? _frameObject;
    private readonly XamlNameScope _names;
    private readonly Dictionary<Type, object> _localServices = new();
    private object? _root;
    private object? _intermediateRoot;
    public XamlRuntimeContext(IServiceProvider? outer = null, object? root = null, Uri? baseUri = null, Func<XamlRuntimeContext, Type, object?>? services = null)
    { _outer = outer; _root = root; _intermediateRoot = root; BaseUri = baseUri; _services = services; _names = new(); Session = new(); }
    private XamlRuntimeContext(XamlRuntimeContext parent, object? frameObject, object? targetObject, object? targetProperty, string? nodeKey, bool newScope)
    {
        _outer = parent._outer; _services = parent._services; _parent = parent; _frameObject = frameObject;
        _root = parent.RootObject; _intermediateRoot = newScope ? null : parent.IntermediateRootObject;
        _names = newScope ? new() : parent._names; Session = newScope ? new() : parent.Session;
        BaseUri = parent.BaseUri; TargetObject = targetObject; TargetProperty = targetProperty; NodeKey = nodeKey ?? parent.NodeKey;
    }
    public XamlRuntimeSession Session { get; }
    public object? RootObject => _root ?? _parent?.RootObject;
    public object? IntermediateRootObject => _intermediateRoot ?? _parent?.IntermediateRootObject;
    public object? TargetObject { get; }
    public object? TargetProperty { get; }
    public string? NodeKey { get; }
    public Uri? BaseUri { get; set; }
    public IEnumerable<object> Parents
    {
        get { for (var current = this; current != null; current = current._parent) if (current._frameObject != null) yield return current._frameObject; }
    }
    public XamlRuntimeContext Push(object value, string key)
    {
        if (_root == null && _parent == null) _root = value;
        if (_intermediateRoot == null) _intermediateRoot = value;
        Session.Register(key, value, NodeKey);
        return new(this, value, TargetObject, TargetProperty, key, false);
    }
    public XamlRuntimeContext ForTarget(object target, object? property) => new(this, null, target, property, NodeKey, false);
    public XamlRuntimeContext CreateDeferredScope(IServiceProvider? services = null) => new(this, null, TargetObject, TargetProperty, null, true);
    public object? GetService(Type serviceType)
    {
        if (serviceType == null) throw new ArgumentNullException(nameof(serviceType));
        if (serviceType == typeof(IServiceProvider) || serviceType == typeof(XamlRuntimeContext) || serviceType == typeof(IXamlRootObjectProvider) || serviceType == typeof(IXamlProvideValueTarget) || serviceType == typeof(IXamlParentStackProvider) || serviceType == typeof(IXamlUriContext)) return this;
        if (_localServices.TryGetValue(serviceType, out var local)) return local;
        for (var parent = _parent; parent != null; parent = parent._parent) if (parent._localServices.TryGetValue(serviceType, out local)) return local;
        return _services?.Invoke(this, serviceType) ?? _outer?.GetService(serviceType);
    }
    public void AddService(Type contract, object instance) => _localServices[contract] = instance;
    public void RegisterName(string name, object value) => _names.Register(name, value);
    public T ResolveName<T>(string name) => (T)_names.Resolve(name);
    public void Defer(Action assignment) => _names.Defer(assignment);
    public void Complete(object root) { _names.Complete(); Session.Attach(root); }
}

using XamlG.Runtime;
using Xunit;
namespace XamlG.Tests;
public sealed class RuntimeTests
{
    [Fact]
    public void FramesPreserveTargetsAndParentOrder()
    {
        var root = new object(); var child = new object(); var context = new XamlRuntimeContext(root: root);
        var frame = context.Push(root, "root").Push(child, "child").ForTarget(child, "Text");
        Assert.Same(root, frame.RootObject); Assert.Equal(new[] { child, root }, frame.Parents); Assert.Equal("Text", frame.TargetProperty);
    }
    [Fact]
    public void ForwardNameFixupsRunAtCompletion()
    {
        var context = new XamlRuntimeContext(); var expected = new object(); object? actual = null;
        context.Defer(() => actual = context.ResolveName<object>("later")); context.RegisterName("later", expected); context.Complete(new object());
        Assert.Same(expected, actual);
    }
    [Fact]
    public void PropertyBatchIsRevisionCheckedAndRollbackSafe()
    {
        using var session = new XamlRuntimeSession(); var a = 1; var b = 2;
        session.RegisterProperty("root", "A", () => a, value => a = value);
        session.RegisterProperty("root", "B", () => b, value => { if (value == 99) throw new InvalidOperationException("Rejected"); b = value; });
        var rejected = session.Apply(0, new[] { new XamlPropertyUpdate("root", "A", 5), new XamlPropertyUpdate("root", "B", 99) });
        Assert.False(rejected.Applied); Assert.Equal(1, a); Assert.Equal(2, b); Assert.Equal(0, session.Revision);
        Assert.True(session.Apply(0, new[] { new XamlPropertyUpdate("root", "A", 7) }).Applied); Assert.Equal(7, a);
        Assert.False(session.Apply(0, Array.Empty<XamlPropertyUpdate>()).Applied);
    }
    [Fact]
    public void BatchRejectsInvalidTypesBeforeCallingAnySetter()
    {
        using var session = new XamlRuntimeSession(); var value = 1;
        session.RegisterProperty("root", "Value", () => value, replacement => value = replacement);
        Assert.False(session.Apply(0, new[] { new XamlPropertyUpdate("root", "Value", "bad") }).Applied); Assert.Equal(1, value);
    }
}
